package investigation

// BuildDefensivePlan starts with a user-selected asset/time range and evidence,
// without inventing a vulnerability. An optional finding is handled separately
// by the case snapshot and does not establish that an intrusion occurred.
func BuildDefensivePlan() Plan {
	return Plan{EngineVersion: EngineVersion, Method: "Log-based independent investigation", Family: "defensive",
		Summary: "Review observational behavior and normal alternatives in the actual log of the selected target and period.",
		Hypotheses: []Hypothesis{
			{ID: "path_access", Title: "Access Log of the Investigation Scope", Statement: "Checks access recorded in the log. Access history alone does not confirm attacks or breaches.", RequiredLogs: []string{"Request/audit log of selected target"}, RequiredFields: []string{"Timestamp", "Target", "Path or Event Type"}, Hunt: "Check the events that match the survey target, duration, and route, and separate the registered ARTEX verification request.", BenignAlternatives: []string{"Normal User Activity", "Approved Security Checks", "Operation/Monitoring Work"}, NextSteps: []string{"Contrast the original event with the approved work history."}},
			{ID: "multi_path", Title: "Request flow from the same log source", Statement: "We will review the request for multiple routes from the same source, destination, session, or departure. We do not confirm the same actor with the same IP alone.", RequiredLogs: []string{"Web Requests/Session Logs"}, RequiredFields: []string{"Timestamp", "Target", "Path", "Session or Departure"}, Hunt: "Check different route requests within ten minutes from the same source and contrast them with normal resource loading.", BenignAlternatives: []string{"Normal browser request", "NAT·Shared Proxy", "Approved Checks"}, NextSteps: []string{"Review the request flow with session, account, and operation history."}},
			{ID: "additional_evidence", Title: "Evidence of alarm and follow-up activities", Statement: "The alarm itself and the success of the attack are distinguished. Authentication, host, and network activities are reviewed when the original log is available.", RequiredLogs: []string{"Alarm Source", "Required authentication, host, network log"}, RequiredFields: []string{"Timestamp", "Target", "Event Type", "Account or Session"}, Hunt: "Check the source alarm and record the required additional logs and scope of the investigation.", BenignAlternatives: []string{"False positive", "Approved management tasks"}, NextSteps: []string{"Don't estimate missing logs and get the data you need."}},
		}, Limitations: []string{"This record is an independent defense investigation that began without a vulnerability diagnosis.", "Static analysis cleans up events and limited request flows in scope and does not confirm whether they are breached.", "AI investigations start separately and use only read-only grounds within the permissible range."}}
}
